bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder,setDefaultAutoSelectFamily} from 'node:dns';
import pg from 'pg';
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createGateOwner} from '/opt/videobot/owner/gateOwner.mjs';
import {createPostgresListingStore} from '/opt/videobot/src/sales/pgListings.mjs';
import {createPostgresPostingReceiptStore} from '/opt/videobot/src/sales/pgPostingReceipts.mjs';
import {publishVideoListing} from '/opt/videobot/src/telegram/paidListingPublisher.mjs';
const env=process.env;
const listingId='starsrepair4701_20261123';
const originalPaidMessage=4701;
const dburl=env.VIDEOBOT_DATABASE_URL_FILE
 ? readPrivateToken(env.VIDEOBOT_DATABASE_URL_FILE)
 : 'postgresql://'+encodeURIComponent(env.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+env.VIDEOBOT_DB_HOST+':5432/videobot';
const pool=new pg.Pool({connectionString:dburl,max:2,connectionTimeoutMillis:5000});
const outbound=createCreatorTelegramFetch(globalThis.fetch);
const api=createTelegramBotApi({token:readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:outbound.fetch,timeoutMs:25000,baseUrl:env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
try{
 const prior=await pool.query("SELECT l.* FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE r.paid_message_id=$1 AND r.status='sent'",[originalPaidMessage]);
 if(prior.rowCount!==1)throw Error('ORIGINAL_VERIFIED_RECEIPT_MISSING');
 const l=prior.rows[0];
 if(l.status!=='published'||l.price_stars!==10||
    !l.rights_verified||!l.adult_consent_verified||!l.fee_terms_accepted_at||
    l.management_fee_bps!==3000||!l.paid_video_file_id||!l.thumbnail_file_id||!l.sample_file_id)
   throw Error('ORIGINAL_SALE_RIGHTS_OR_PRICE_CHANGED');
 if(Number(env.VIDEOBOT_VIDEO_SALE_THREAD_ID)!==1695)throw Error('ORIGINAL_TOPIC_CHANGED');
 const store=createPostgresPostingReceiptStore(pool);
 const priorReceipt=await store.read(listingId+':1');
 if(priorReceipt){
  if(priorReceipt.status==='sent'){
   console.log('IDEMPOTENT_ALREADY_SENT=YES');
   console.log('PAID_MESSAGE_ID='+priorReceipt.paidMessageId);
   process.exitCode=0;
  } else {throw Error('PREVIOUS_ATTEMPT_REQUIRES_RECONCILIATION');}
 } else {
  const added=await pool.query(
    "INSERT INTO videobot_listings (listing_id,seller_user_id,revision,title,description,price_stars,price_mode,thumbnail_file_id,sample_file_id,sample_duration_seconds,paid_video_file_id,rights_verified,adult_consent_verified,fee_terms_accepted_at,creator_terms_version,creator_terms_url,management_fee_bps,fee_policy_id,status) SELECT $1,seller_user_id,1,title,description,price_stars,price_mode,thumbnail_file_id,sample_file_id,sample_duration_seconds,paid_video_file_id,rights_verified,adult_consent_verified,fee_terms_accepted_at,creator_terms_version,creator_terms_url,management_fee_bps,fee_policy_id,'ready' FROM videobot_listings WHERE listing_id=$2 AND status='published' AND price_stars=10 AND rights_verified=TRUE AND adult_consent_verified=TRUE AND fee_terms_accepted_at IS NOT NULL AND management_fee_bps=3000 ON CONFLICT(listing_id) DO NOTHING RETURNING listing_id",
    [listingId,l.listing_id]);
  const listings=createPostgresListingStore(pool);
  const candidate=await listings.getOwned(Number(l.seller_user_id),listingId);
  if(!candidate||candidate.status!=='ready'||candidate.revision!==1||
     candidate.paidVideo?.fileId!==l.paid_video_file_id ||
     candidate.thumbnail?.fileId!==l.thumbnail_file_id ||
     candidate.sample?.fileId!==l.sample_file_id)
    throw Error('REPAIR_LISTING_NOT_EXACT_OR_ALREADY_MODIFIED');
  const owner=await createGateOwner({telegramApi:api,pool,env});
  const topic=await owner.getVerifiedVideoTopic();
  if(topic.chatId!==-1002373696859||topic.threadId!==1695||
     topic.purpose!=='video_sale'||topic.verified!==true)
    throw Error('PUBLISH_TOPIC_NOT_VERIFIED');
  console.log('PREFLIGHT_NATIVE_PAID_MEDIA_OK=YES');
  const receipt=await publishVideoListing({
   listing:{...candidate,ownerConfirmedPublish:true,feeTermsAccepted:true},
   getVerifiedVideoTopic:owner.getVerifiedVideoTopic,
   verifyMembership:owner.verifyMembership,
   verifyReview:owner.verifyReview,
   verifyRelease:owner.verifyRelease,
   store,telegramApi:api
  });
  if(receipt.posted!==true||!Number.isSafeInteger(receipt.paidMessageId))
    throw Error('NATIVE_PAID_MEDIA_ACK_NOT_VERIFIED');
  await listings.markPublished(Number(l.seller_user_id),listingId,1,receipt);
  const readback=await store.read(listingId+':1');
  const current=await listings.getOwned(Number(l.seller_user_id),listingId);
  if(readback?.status!=='sent'||readback?.paidMessageId!==receipt.paidMessageId||current?.status!=='published')
    throw Error('PAID_POST_READBACK_NOT_CONFIRMED');
  console.log('NATIVE_STARS_PAID_POST=PASS');
  console.log('NEW_PAID_MESSAGE_ID='+receipt.paidMessageId);
  console.log('NEW_FREE_MESSAGE_IDS='+receipt.freeMessageIds.join(','));
  console.log('EXISTING_4691_4701_UNTOUCHED=YES');
 }
}catch(error){
 console.error('STARS_REPAIR_STATE=FAIL '+String(error?.message??'unknown').replace(/https?:\/\/\S+/g,'[redacted]').slice(0,140));
 process.exitCode=75;
}finally{await pool.end().catch(()=>{});await outbound.close().catch(()=>{});}
JS
